import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"西溪易說卷七","description":"西溪易說 - 西溪易說卷七","frontmatter":{"title":"西溪易說卷七","description":"西溪易說 - 西溪易說卷七"},"headers":[],"relativePath":"classics/xixi/008.md","filePath":"classics/xixi/008.md"}'),i={name:"classics/xixi/008.md"};function r(c,p,_,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="西溪易說卷七" tabindex="-1">西溪易說卷七 <a class="header-anchor" href="#西溪易說卷七" aria-label="Permalink to “西溪易說卷七”">​</a></h1><p>欽定四庫全書</p><p>宋李過撰</p><p>䷞ 艮下兌上</p><p>鹹。</p><p>鹹：亨，利貞，取女吉。彖曰：鹹，感也。柔上而剛下，二氣感應以相與，止而說，男下女，是以「亨，利貞，取女吉」也。天地感而萬物化生，聖人感人心而天下和平。觀其所感，而天地萬物之情可見矣。</p><p>上經首乾、坤，下經首鹹、恆。序卦雲：「有天地，然後有萬物。有萬物，然後有男女。有男女，然後有夫婦。有夫婦，然後有父子。有父子，然後有君臣。有君臣，然後有上下。有上下，然後禮義有所錯。」鹹、恆者，夫婦之道也。鹹言夫婦之感，怕言夫婦之正。感道莫感於夫婦，故男下女為鹹之義。然鹹，感也，不曰感而曰鹹，謂感人之道不可以有心也。易無思也，無為也，寂然不動，感而遂通天下之故。有心於求感，非易之道也，故去其心而名卦以「鹹」。鹹，皆也。無心於感者，無所不感也。大而天地陰陽之交，小而啁啾牝壯之好，天機所動，不約自隨。聖人洗心退藏，萬物酬酢，相代乎吾前，所存者神，所過者化，此心雖不隨於物，而天下萬物卒不能外聖人之心，則得所感矣。曰：「鹹，亨」，感而亨者也。「利貞」，感以正也。「取女吉」，人道之感，莫大於夫婦。兌上艮下，男下女，取女之義也。彖：「鹹」，感也，柔上而剛下。卦自否來，「否」，天地不交也。今六爻一柔，上居上六，上九一剛，下居九三，是天地之氣交也。故上體成兌，下體成艮。艮為少男，兌為少女，艮止而兌說，故曰「二氣感應以相與」。止而說，男下女，是以「亨，利貞，取女吉」也。泛觀天地萬物，機者自動，籟者自鳴，同聲必相應，同氣必相求，莫不有自然之感。聖人之治天下，感應之道，亦若是而已矣。故曰：「觀其所感，而天地萬物之情可見矣。」</p><p>象曰：山上有澤，「鹹」，君子以虛受人。澤本在山下而山上澤之，澤之氣通乎山也。山澤通氣，自然之感，「以虛受人」，天下之理，惟至虛者為能受，苟先者以安乎其中，雖投之不入矣。</p><p>初六，鹹其拇。象曰：「鹹其拇」，志在外也。</p><p>金卦六又為人象。初為拇，二為腓，三為股，四為心，五為脢，六輔頰舌。惟四得貞吉，餘爻皆不善。蓋三爻為足，足欲動而感；五為脢，以胸感；上為口，以言感；皆非感之善。四守貞，無心於感者也，故於四爻發明感人之道。初居最下，拇，大指也，應在四，足往而拇隨，以拇而感，未能感也。象曰：志在外，言在應四也。</p><p>六二，鹹其腓，兇。居吉。象曰：雖「兇吉」，順不害也。</p><p>二居拇上，足之肚也，行而感則兇，順而居則吉，設兩端以聽其自擇也。象曰「順不害也」，言能順則不害也。</p><p>九三，鹹其股，執其隨，往吝。象曰：「鹹其股」，亦不處也；志在隨人，所執下也。</p><p>三，下體之上；股，足之上也。拇而腓，從股以動者也。三位又不正，舉股而動以隨人，其感亦勞矣，守此吝道也。象曰：「鹹其股」，亦不知處也；「志在隨人」，所執下也。</p><p>九四，貞吉，悔亡。憧憧往來，朋從爾思。象曰：「貞吉悔亡」，未感害也。「憧憧往來」，未光大也。</p><p>四處心位，有心於感則害鹹體，故不言心。曰「貞吉悔亡」，守貞不動，則得鹹之吉而「悔亡」矣。萬物往來於吾前，苟此心憧憧然與之為往來，是以思感也。以思而感，則思之所不及者不能感矣，但朋從而已。象曰：未感害也。貞而不感，未有害也；以思而感，則未光大也。繫辭：「子曰：天下何思何慮！天下同歸而殊塗，一致而百慮，天下何思何慮！日往則月來，月往則日來，日月相推而明生焉；寒往則暑來，暑往則寒來，寒暑相推而歲成焉。往者屈也，來者信也，屈信相感而利生焉。」尺蠖之屈，以求信也；龍蛇之蟄，以存身也。精義入神，以致用也。利用安身，以崇德也。過此以往，未之或知也。窮神知化，德之盛也。九五：鹹其脢，無悔。象曰：「鹹其脢」，志末也。</p><p>「脢」，心至輔之下，人之胸也。以胸感人，怛然忘懷，可以「無悔」矣。然有胸無心，又感道之病，蓋此心又不可無所主也，故象曰：「志末也。」</p><p>又說四以心感，則曰「悔亡」，是有悔而亡也；五以胸感，則曰「無悔」，是無復有悔也，則胸感為善矣。知胸感為感之善，則知心感為感之末，故象曰：「志末也。」</p><p>上六：鹹其輔、頰、舌。象曰：「鹹其輔、頰、舌」，滕口說也。上以口舌感人，其感人也末矣。合鹹卦六爻觀之，辭皆未善。四得「貞吉」，又有「憧憧往來」之戒，然則感道安在？聖人故曰：「易無思也，無為也，寂然不動，感而遂通天下之故。」非天下之至誠，其就能與於此夫惟盡誠者然後能感，所以六爻皆未善，以見感道之難。䷟ 巽下震上</p><p>恆，</p><p>恆：亨，無咎，利貞，利有攸往。彖曰：恆，久也。剛上而柔下，雷風相與，巽而動，剛柔皆應，恆。「恆，亨，無咎，利貞」，久於其道也。天地之道，恆久而不已也。「利有攸往」，終則有始也。日月得天而能久照，四時變化而能久成，聖人久於其道，而天下化成。觀其所恆，而天地萬物之情可見矣。「恆」，久也。天下之理，可以常久而不變者，以其正也。卦震上巽下，「鹹」男下女，夫婦之始。今也男上女下，男外女內，為夫婦之正。道之可常者，惟其正而已。曰：「恆，亨，利貞，無咎」，道之恆者，可以通行而「無咎」也。「利貞」，利乎正也。正則可「恆」矣。「利有攸往」，乃所以為「恆」也。往則不息，不息則久，天地之道不過如此。子思得此而言中庸。蓋中者，正也。庸者，常也。惟中故可恆，恆則不息，不息則悠久，悠久則無疆，其此之謂歟？彖曰：「恆」，久也。剛上而柔下，雷風相與，「巽」而動，剛柔皆應，恆而就。卦取恆義也。卦自「泰」來。「泰」，天地之交也。今初九一剛，上居九四，六四一柔，下居初六，故上體為「震」，下體為「巽」。震為長男，「巽」為長女，男上而女下，男女定位也。其位既定，然後二象相與，剛動於外，柔巽於內，上下二體，剛柔皆相應，所以為「恆」也。「恆」：「亨，無咎，利貞」，久於其道也。天地之道，恆久而不已也。「利有攸往」，終則有始也。天地之道，所以恆久者，在於不已。「利有攸往」，不已之事也。曰「終則有始」，蓋天地之道，終始往來，相循於無窮，所以為恆也。所存者益神，所過者常化。「貞無咎」，所存者神之謂也；「利有攸往」，所過者化之謂也。此「終則有始」之意也。日月得天，而能久照，四時變化，而能久成，聖人久於其道，而天下化成。日月四時，天地所以為常也，故以其化而見其恆。久於其道，聖人所以體其常也，故以其常而見其化。泛觀天地日月之往來，陰陽之代謝，百穀草木之榮悴，與夫生民之日用飲食，其相循於無窮者，皆常之功用也。故曰：「天生萬物之情可見矣。」</p><p>象曰：雷風，恆，君子以立不易方。</p><p>震為雷，巽為風。天下之至震動者，莫如此二者。雖聖人至此，亦當祗畏，故迅雷烈風必變。蓋眾人當風雷震動之時，則必倉皇自失，改其常度，與平居暇日全相背也。惟德至於舜，然後能弗迷。是舜能有恆，故處雷風震動之時，視之如平日也。於此之時，視之如平日，然後見胸中之有常。故君子於此，當「立不易方」。若做過這事，確爾如是，初不因人作輟也。</p><p>初六，浚恆，貞兇，無攸利。象曰：「浚恆」之兇，始求深也。浚，深也。人情物理，深必有漸。初處恆之始，遽以深為常，既兇而且無所利也。人道之交，如君臣相交，夫婦相與，朋友相際，其始皆未可深也。由淺而深，其深必久；始而求深，其壞必遽。象曰：始求深也。賈誼、劉蕡，皆始求深者也。</p><p>九二：悔亡。象曰：九二「悔亡」，能久中也。</p><p>以久居二，剛柔得中，可恆之道也，故「悔亡」。象曰：「九二悔亡」，能久中也。以剛柔得中，故可久也。子思言「中庸」，蓋本諸此。惟中故可常也。然九二所以得剛柔之「中」者，九剛也，二柔也。剛柔兩用，所以為中也。中庸曰：「舜執兩端，用其中於民。」蓋立道以來，合下有兩。立天之道，曰陰與陽；立地之道，曰柔與剛，皆兩也。執兩所以用中，執一則非中也。二之得中，其謂是歟！</p><p>九三：不恆其德，或承之羞，貞吝。象曰：「不恆其德」，無所容也。</p><p>以剛居剛而位不中，是不恆其德，則羞辱或承之矣。以此而不變，吝也。象曰：「無所容也。」為眾所羞，則無所容其身矣。子曰：「不得中行而與之，必也狂狷乎！」「中行」，恆德之人也；「狂狷」，過與不及者也。恆卦六爻，惟二與五以中行而有常，故二「悔亡」，而五「恆其德貞」。初與四不及中，三與上又過中，皆「不恆其德」者也。故初「浚恆兇」，三不恆而「羞」，四「田無禽」，上「振恆兇」也。</p><p>九四，田無禽。象曰：久非其位，安得禽也？</p><p>上體五得中，四位不中，「田」所以「從禽」也。然亦必以正，正所謂範我馳驅詭遇之禽，雖若丘陵，君子不取也，故曰：「田無禽。」以此而田，未必「無禽」，然猶「無禽」也。象曰：「久非其位」，蓋君子之恆者也，惟正而已，所謂「立天下之正位」是也。況非其位而可久乎？所以「無禽」也。</p><p>六五，恆其德，貞，婦人吉，夫子兇。象曰：「婦人貞吉」，從一而終也；「夫子制義」，從婦兇也。</p><p>五得中，能「恆其德」者，故曰「恆其德，貞」。卦男上女下，五雖男位，而以六為常；二雖女位，而以九為常。以五之柔，下從二之剛，夫柔而婦剛，非可恆也，故曰「婦人吉」。謂貞於柔，婦人則吉也；夫子貞於柔，兇之道也。故象曰：「婦人貞吉，從一而終也。夫子制義，從婦兇也。」謂從婦人之道也。</p><p>上六：振恆，兇。象曰：「振恆」在上，大無功也。</p><p>處「震」之終，「震」，動也。位又不正，以妄動為常，兇道也。故象曰：「振恆在上，大無功也。」合恆卦六爻觀之，辭亦未善。初、三、四、上皆兇，二、五雖得中，以「夫子制義」言之，又失剛柔之正。然則「恆」道安在？聖人故曰：「中庸之為德，其至矣乎？民鮮能久矣。」久於中，亦聖人事也。夫惟聖人然後能體恆，所以六爻皆未善，以見常道之難。䷠ 艮下乾上</p><p>遁</p><p>遁：亨，小利貞。彖曰：「遁，亨」，遁而亨也。剛得位而應，與時行也。「小利貞」，浸而長也。遁之時義大矣哉！</p><p>一陰生姤，二陰生遁，陰長而陽遁也。小人漸長，則君子當見幾而去，所謂隱居以求其志，行義以達其道，曰「遁亨」。雖遁也，乃所以為「亨」。然二陰漸進，猶未盛也，勢尚可為。君子皆全身而去，非所望也。聖賢處亂世，當亂形未見，正當維持危行。遁言以漸而正之，不害為遁也，故曰「小利貞」。春秋、戰國之時，人道絕矣，而孔、孟猶不去，蓋聖賢無不可為之時，如曰「天下有道，不與易也」。聖人正欲易亂世，如沮、溺輩，則無如之何也。但以陰陽二氣觀之，一陰生午，二陰生未，陽宜遁矣，而勢熖特盛，畢競還他，成許多生物之功然後已。全身遠害，特遁之細事也。彖曰：「遁亨」，遁而亨也。言遁乃所以「亨」也。剛當位而應，與時行也。二陰雖長，九五以剛居君位，六二居中，而五應之，君臣之情未睽也，烏可遽去哉？當觀時而動也。「小利貞」，浸而長也。謂陰長以漸，尚可貞也。遁之時義大矣哉！謂非止為苟去也。卦中六爻，惟上九「肥遁」，五為「嘉遁」之主。下四爻皆可以去，可以無去者也。</p><p>象曰：天下有山，「遁」，君子以遠小人，不惡而嚴。</p><p>天至高也，天下便見山。極高之山，所謂「泰山岩巖，魯邦所瞻」者是也。世不亂，無以見君子。小人方長，君子為天下所屬望，正當巍巍自立，使小人不可得而依附，則不能為己害矣。「不惡而嚴」，乃遠小人之道也。</p><p>初六，遁尾，厲，勿用有攸往。象曰：「遁尾」之厲，不往何災也！初居遁之始，位最微，「尾」，在後之物也。象既遁矣，己獨在後，見幾不敏也，必為小人所害，故「厲」。然己處下，不繫成敗，可以去，可以無去者也，故「勿用有攸往」。象曰：「不往何災」，與其遁而危，不若不遁之無災也。古之人有仕亂世而不去者多矣。位，卑位也。六二，執之用黃牛之革，莫之勝說。象曰：執用黃牛，固志也。</p><p>二居中，九五之君，剛當位而應己，君臣之情甚厚也。故二爻特不言遁，是可以無遁也。所當固守其志，不為小人所亂。「黃牛之革」，言其自固，所謂危行也。「莫之勝說」，言其避禍，所謂言遜也。危行以自固，遜言以避禍，雍容於群小之間，而使國勢猶有所倚，則六二之為也。象曰：固志也。九三，系遁，有疾厲。畜臣妾，吉。象曰：「系遁」之厲，有疾憊也。「畜臣妾吉」，不可大事也。</p><p>三與下二陰同體，為小人所拔系，不得遁也。自古小人之進，皆君子引援之力，其引援不知其害己也，故曰「系遁，有疾厲」。然小人何世無之，不宜引致高位，以臣妾畜之則吉矣，非可使在人上。象曰：「有疾憊也」，謂小人拔系，必為己害也。「不可大事也」，小人大用則必亂。</p><p>九四，好遁，君子吉，小人否。象曰：君子「好遁」，「小人否」也。四離下體而居上，無所牽繫，見幾而去，得遂其志願而遁也，故曰「好遁」。君子得遁，則君子之道伸矣。世皆小人，則人心離而生亂，則小人必為天下戮，實小人之否也。故一君子在小人之間，猶為小人之福，君子去則小人危矣。</p><p>九五，嘉遁，貞吉。象曰：「嘉遁貞吉」，以正志也。</p><p>以陽剛之君而居中，所謂陽當位者也。己為遁之主，使小人得進而君子棄去，誰之咎也？必不得已，當致禮以褒寵之，以示崇尚之意，故曰「嘉遁」。如鳴騶入谷，鶴書赴隴，物色丘園，皆所以嘉其遁也。使其肯來歟？尚足以共國；使其不肯來歟，亦清風義槩，又賴以激貪而起懦，故爻曰「貞吉」，象曰「以正志也」。</p><p>上九：肥遁，無不利。象曰：「肥遁無不利」，無所疑也。</p><p>處遁之上，在一卦之外，高飛遠舉，翩然長往，本無心於用世。以遁為肥者，子云所謂「山雌之肥」是也，非如下四爻，意在得時行道，遇世不可為而後遁者也。之人也，飄然物外，憂患之所不加，故曰「無所疑也」。䷡ 乾下震上 大壯</p><p>大壯利貞。彖曰：「大壯」，大者壯也。剛以動，故壯。「大壯利貞」，大者正也。正大而天地之情可見矣。</p><p>四陽盛長，陽為大，大者壯也。「利貞」，陽壯而正也。陽生至四，陰凝始退，陽氣方正，正故利也。彖曰：「大壯」，大者壯也。剛以動，故壯。「大壯利貞」，大者正也。正大而天地之情可見矣。大者正也。陽為大，陽進至四，陽，壯也。下體剛，上體動，以剛而動，故名卦以壯也。貞，正也。「大壯，利貞」，陽進至四，陽氣始正也。陽正則萬物發生。生物之心，天地之真情也，故曰：「天地之情可見矣」。全卦六爻，以剛動為義。凡人之生，所稟不同，而血氣之剛為難制，故君子必以理義制之。四陽方壯，不可御也，猶人血氣之盛，故六爻皆以進為戒，以貞為吉。惟四爻陽正，以正而動。君子之道，則曰「壯於大輿之輹」。</p><p>象曰：雷在天上，「大壯」；君子以非禮弗履。程氏曰：雷震於天上而壯也。君子觀其壯之象，以行其壯。君子之大壯者，莫若克己復禮。古人云：「自勝之謂強。」中庸於「和而不流，中立而不倚」，皆曰「強哉矯」。赴湯火，蹈白刃，一勇之決者可能也，至於克己復禮，則非君子之大壯不可能也，故云「非禮弗履」。</p><p>初九，壯於趾，徵兇，有孚。象曰：「壯於趾」，其孚窮也。</p><p>初陽方壯，其心常動，趾所以行也。以剛而動，未必中理，徵而得兇，既兇而窮，天理乃復，故曰「徵兇有孚」。象曰：「其孚窮也」，賴乎困窮而天理復還也。所謂困於心衡於慮而後得，操心危、慮患深而後達者也。</p><p>九二，貞吉。象曰：「九二貞吉」，以中也。</p><p>剛而得中，能禮者也。以理勝氣，守中而吉。象曰：「九二貞吉」，以中也。</p><p>九三，小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。象曰：「小人用壯」，君子罔也。</p><p>三以剛居剛，位不中正，小人處此，必用其壯，君子則忘其壯，理義與血氣之別也。貞守其剛而不變則厲。羝羊，喜觸之物，三勇於進，四一陽在上止之，觸而不勝，至羸其角，小人動乎血氣，自取橈敗之象也。三居剛極，故設此戒。</p><p>九四，貞吉，悔亡。藩決不羸，壯於大輿之輹。象曰：「藩決不羸」，尚往也。</p><p>陽進至四，陽氣正矣，壯而得正，吉且悔亡。二陰在上，其藩已決，可無羸角之患。輹所以行也，以此而行，莫之能御矣。象曰「尚往也」，陽壯至四而得正，故可往也，與下體異。</p><p>六五，喪牛於易，無悔。象曰：「喪牛於易」，位不當也。</p><p>一陰在五，四陽並進，非己之能有；五陽生則為夬，一陰必決，非可久居，故群陽之進，非一陰能主，喪之而去，略無芥葉則無悔。猶君子並進，不容小人更據尊位，所宜退聽以避賢路，然後可免也。象曰「位不當也」，謂陽進此則決矣，以陰居之，故不當也。上六，羝羊觸藩，不能退，不能遂，無攸利，艱則吉。象曰：「不能退，不能遂」，不詳也。「艱則吉」，咎不長也。</p><p>陽壯至六則成純乾，其陽必亢，亢則不知進退存亡，故曰「不能退，不能遂，無攸利」也。「艱則吉」，謂知進退存亡之理而自守則吉，蓋亢而能用故也。象曰「不詳也」，謂不明消息之理也。曰「咎不長」者，以陽為君子，君子知艱，故「咎不長」。然上體六陽進此為義，故六五一爻，當以夬卦五爻觀，上六一爻，當以乾卦上爻觀。䷢ 坤下離上</p><p>晉：</p><p>晉：康侯用錫馬蕃庶，晝日三接。彖曰：「晉」，進也。明出地上，順而麗乎大明，柔進而上行，是以「康侯用錫馬蕃庶，晝日三接」也。</p><p>「晉」，明也，進也。明體在上，坤進而上行。諸侯覲王，王錫之殊禮，而其數有加也。故卦辭止雲：「康侯用錫馬蕃庶，晝日三接。」彖曰：「晉」，進也。明出地上，順而麗乎大明。離居坤上，大明之世也。六五以柔順之道麗乎君位也。「柔進而上行」，三為諸侯之位，下卦純柔，體自進至三，方得諸侯之位。又進至五，方得受錫。故五為晉之主，三為康侯之位。進而上行，五接以禮，是康侯用此卦而「錫馬蕃庶，晝日三接」也。</p><p>象曰：明出地上，晉。君子以自昭明德。</p><p>日出地上，大明之主在上也。居南面以聽天下，諸侯北面而朝之，晉之事也。古者分茅胙土以象賢德，君子必自昭明德，然可可以受王命。初六，晉如摧如，貞吉。罔孚，裕無咎。象曰：「晉如摧如」，獨行正也。「裕無咎」，未受命也。</p><p>卦之三爻為康侯之位，初在下，未得位。晉如，欲上進也；「摧如」，又退折也。未可上進，貞守則吉也，故曰「晉如摧如，貞吉」。「罔孚」，德未孚於眾也，退而自裕以修德，則無咎。象曰：「獨行正也」，獨行吾之正也。「裕無咎」，未受命也。諸侯必受命於天子，以未受命，故未可進也。</p><p>六二，晉如愁如，貞吉。受茲介福，於其王母。象曰：「受茲介福」，以中正也。</p><p>二與五分雖君臣，然非諸侯之位。欲進如又「愁如，愁如」，未得所願也，亦未可進，守貞則吉。六五以柔居君位，是以母道王天下也。二應在五，進而至五，則受錫矣，故曰「受茲介福，於其王母」。言「受茲介福」，必進至王母之所，今尚居二，未可受福也。象曰：以中正也。以進而至五，然後得中正也。</p><p>六三，眾允，悔亡。象曰：「眾允」之志，上行也。三正「康侯」之位，退而至三，可以進矣。初之「罔孚」，眾未允也；二之「愁如」，猶有悔也。三居上位，德孚於眾而眾允，進德所願而悔亡，故曰「眾允悔亡」。如此則可以受錫於王矣。象曰：「眾允」之志，上行也。謂上進於五也。</p><p>九四，晉如鼫鼠，貞厲。象曰：「鼫鼠貞厲」，位不當也。</p><p>四，近卿士之位也。古之諸侯有入為王卿士者。二進覲五而至四，苟有覬覦卿士之心，則覲王之心已不純，故以「鼫鼠」為戒。「鼫鼠」，貪物也，如周人將畀虢公政，鄭伯失卿士之位而怨周，既交惡，又交質，其終也帥師取成周之麥，又取成周之禾，是鼫鼠也，故曰「晉如鼫鼠」。至此固當守而以危懼自戒，則將敬以受錫矣，故曰「貞厲」。象曰「位不當也」，謂此位非諸侯之所當覬也。</p><p>六五：悔亡，失得勿恤。往吉，無不利。象曰：「失得勿恤」，往有慶也。</p><p>進而至五，進於王所矣。君臣交際，享禮命宥，得其所願，悔既亡矣。雖然，惟知覲君而已，錫禮之得與否，勿憂也。錫馬之多，三接之勤，繼此而至矣，故曰「失得勿恤，往吉，無不利」。象曰「往有慶也」，謂勿恤而往，則受殊禮而有慶也。</p><p>上九：晉其角，維用伐邑，厲吉，無咎，貞吝。象曰：「維用伐邑」，道未光也。</p><p>「角」，極也。進而至五，已受錫矣。又進而上，諸侯受錫之極，則命為方伯，錫以斧鉞，使得專征伐。諸侯有不庭者，則奉王命以討之，故曰「晉其角，維用伐邑」。然專征，大事也，必謹奉王命，則吉而無咎，故曰「厲吉，無咎」。然極治之時，為二伯者率東方諸侯入應門左，率西方諸侯入應門右，安有不庭而尚勞征伐哉？至於「維用伐邑」，則亦吝矣，況可恆哉！故曰「貞吝」。象曰「道未光也」。必無事征伐，則方伯之職舉而道光矣。西溪易說卷七，</p>',76)])])}const x=a(i,[["render",r]]);export{m as __pageData,x as default};
